"""PL-03 step 2: whole-period statistics per ticker."""

from __future__ import annotations

from statistics import fmean, stdev

from risk.types import TickerSummary, VolSeries


def summary_stats(vol: VolSeries, periods_per_year: int = 252) -> tuple[TickerSummary, ...]:
    """Annualized return, volatility, Sharpe and last rolling volatility per ticker (RISK-04).

    Spine version: the daily mean and sample stdev of the returns, not annualized; Sharpe is
    their ratio, 0.0 when the stdev is 0.
    """
    returns = vol.returns
    if len(returns.dates) < 2:
        raise ValueError(f"need at least two returns, got {len(returns.dates)}")
    summaries = []
    for ticker in returns.tickers:
        series = returns.values[ticker]
        mean = fmean(series)
        sd = stdev(series)
        summaries.append(
            TickerSummary(
                ticker=ticker,
                ann_return=mean,
                ann_vol=sd,
                sharpe=mean / sd if sd else 0.0,
                last_vol=vol.values[ticker][-1],
            )
        )
    return tuple(summaries)
"""Unit tests for risk.summary.summary_stats (PL-03 step 2, spine: daily mean and stdev)."""

from __future__ import annotations

import json
from pathlib import Path

import pytest

from risk.summary import summary_stats
from risk.types import Returns, VolSeries

SAMPLE = Path(__file__).parents[2] / "contracts" / "risk.VolSeries" / "sample.json"


def _sample_vol() -> VolSeries:
    data = json.loads(SAMPLE.read_text())
    returns = data["returns"]
    return VolSeries(
        returns=Returns(
            base_date=returns["base_date"],
            dates=tuple(returns["dates"]),
            tickers=tuple(returns["tickers"]),
            values={ticker: tuple(values) for ticker, values in returns["values"].items()},
        ),
        window=data["window"],
        annualized=data["annualized"],
        values={ticker: tuple(values) for ticker, values in data["values"].items()},
    )


def _one_ticker(values: tuple[float, ...], vols: tuple[float | None, ...]) -> VolSeries:
    dates = tuple(f"2025-01-0{i + 2}" for i in range(len(values)))
    returns = Returns(base_date="2025-01-01", dates=dates, tickers=("X",), values={"X": values})
    return VolSeries(returns=returns, window=2, annualized=False, values={"X": vols})


def test_sample_gives_one_summary_per_ticker_in_order() -> None:
    result = summary_stats(_sample_vol())
    assert [s.ticker for s in result] == ["AAA", "BBB"]
    aaa, bbb = result
    assert aaa.ann_return == pytest.approx(0.00172997, abs=1e-7)
    assert bbb.ann_return == pytest.approx(0.01777486, abs=1e-7)
    assert aaa.last_vol == pytest.approx(0.1151289288)
    assert bbb.last_vol == pytest.approx(0.3285592270)
    for summary in result:
        assert summary.ann_vol > 0
        assert summary.sharpe == pytest.approx(summary.ann_return / summary.ann_vol)


def test_daily_mean_sample_stdev_and_their_ratio() -> None:
    (summary,) = summary_stats(_one_ticker((0.01, 0.03, 0.05), (None, None, 0.0141)))
    assert summary.ann_return == pytest.approx(0.03)
    assert summary.ann_vol == pytest.approx(0.02)
    assert summary.sharpe == pytest.approx(1.5)
    assert summary.last_vol == pytest.approx(0.0141)


def test_last_vol_is_none_when_the_window_never_filled() -> None:
    (summary,) = summary_stats(_one_ticker((0.01, 0.03), (None, None)))
    assert summary.last_vol is None


def test_flat_returns_give_zero_sharpe() -> None:
    (summary,) = summary_stats(_one_ticker((0.02, 0.02, 0.02), (None, None, 0.0)))
    assert summary.ann_vol == 0.0
    assert summary.sharpe == 0.0


@pytest.mark.parametrize("values", [(), (0.01,)])
def test_fewer_than_two_returns_raises(values: tuple[float, ...]) -> None:
    vol = _one_ticker(values, tuple(None for _ in values))
    with pytest.raises(ValueError, match="at least two returns"):
        summary_stats(vol)
"""Intent tests for risk.summary_stats (RISK-04, TC-07)."""

from __future__ import annotations

import pytest

from risk import Returns, TickerSummary, VolSeries, summary_stats


def _returns(payload: dict) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


def _vol(payload: dict) -> VolSeries:
    return VolSeries(
        returns=_returns(payload["returns"]),
        window=payload["window"],
        annualized=payload["annualized"],
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


def _tc07(golden) -> tuple[tuple[TickerSummary, ...], dict]:
    given, expected = golden("risk", "TC-07")
    return summary_stats(_vol(given["vol"])), expected


@pytest.mark.intent
def test_tc07_one_summary_per_ticker_in_returns_order(golden):
    result, expected = _tc07(golden)
    assert all(isinstance(s, TickerSummary) for s in result)
    assert [s.ticker for s in result] == [row["ticker"] for row in expected["summary"]]


@pytest.mark.intent
def test_tc07_annualized_return_is_252_times_mean(golden):
    result, expected = _tc07(golden)
    tol = expected["tol"]
    by_ticker = {s.ticker: s for s in result}
    for row in expected["summary"]:
        assert by_ticker[row["ticker"]].ann_return == pytest.approx(row["ann_return"], abs=tol)


@pytest.mark.intent
def test_tc07_annualized_vol_is_sqrt252_times_sample_stdev(golden):
    result, expected = _tc07(golden)
    tol = expected["tol"]
    by_ticker = {s.ticker: s for s in result}
    for row in expected["summary"]:
        assert by_ticker[row["ticker"]].ann_vol == pytest.approx(row["ann_vol"], abs=tol)


@pytest.mark.intent
def test_tc07_sharpe_is_the_quotient_and_zero_for_zero_vol(golden):
    result, expected = _tc07(golden)
    tol = expected["tol"]
    by_ticker = {s.ticker: s for s in result}
    for row in expected["summary"]:
        assert by_ticker[row["ticker"]].sharpe == pytest.approx(row["sharpe"], abs=tol)


@pytest.mark.intent
def test_tc07_reports_the_last_rolling_vol(golden):
    result, expected = _tc07(golden)
    tol = expected["tol"]
    by_ticker = {s.ticker: s for s in result}
    for row in expected["summary"]:
        last_vol = by_ticker[row["ticker"]].last_vol
        assert last_vol is not None
        assert last_vol == pytest.approx(row["last_vol"], abs=tol)


@pytest.mark.intent
def test_fewer_than_two_returns_raises_value_error(contract_sample):
    payload = contract_sample("risk.VolSeries")
    returns = payload["returns"]
    one_return = {
        "returns": {
            "base_date": returns["base_date"],
            "dates": returns["dates"][:1],
            "tickers": returns["tickers"],
            "values": {t: v[:1] for t, v in returns["values"].items()},
        },
        "window": payload["window"],
        "annualized": payload["annualized"],
        "values": {t: [None] for t in payload["values"]},
    }
    with pytest.raises(ValueError, match=r"(?i)return"):
        summary_stats(_vol(one_return))
"""risk's boundary types: returns, volatility, summaries, drawdowns and the report."""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass


@dataclass(frozen=True)
class Returns:
    """Daily log returns, dated on the prices' dates after the first, which is `base_date`."""

    base_date: str
    dates: tuple[str, ...]
    tickers: tuple[str, ...]
    values: Mapping[str, tuple[float, ...]]


@dataclass(frozen=True)
class VolSeries:
    """Rolling volatility aligned to `returns.dates`; None until `window` earlier returns exist."""

    returns: Returns
    window: int
    annualized: bool
    values: Mapping[str, tuple[float | None, ...]]


@dataclass(frozen=True)
class TickerSummary:
    """One ticker's whole-period statistics."""

    ticker: str
    ann_return: float
    ann_vol: float
    sharpe: float
    last_vol: float | None


@dataclass(frozen=True)
class Drawdown:
    """One ticker's worst fall from a peak: `depth` <= 0, `peak_date` <= `trough_date`."""

    ticker: str
    depth: float
    peak_date: str
    trough_date: str


@dataclass(frozen=True)
class Report:
    """The written report: one row per ticker, sorted, the same rows as the file."""

    path: str
    rows: tuple[Mapping[str, object], ...]
"""PL-02 step 4: annualize volatility over trading days."""

from __future__ import annotations

import dataclasses
import math

from risk.types import VolSeries


def annualize(vol: VolSeries, periods_per_year: int = 252) -> VolSeries:
    """Each daily volatility times the square root of `periods_per_year` (RISK-03).

    Gaps (None) stay gaps; the result is marked annualized.
    """
    if vol.annualized:
        raise ValueError("vol is already annualized")
    scale = math.sqrt(periods_per_year)
    values = {
        ticker: tuple(None if v is None else v * scale for v in series)
        for ticker, series in vol.values.items()
    }
    return dataclasses.replace(vol, annualized=True, values=values)
